package beads

import (
	"encoding/json"
	"testing"

	"github.com/gastownhall/gascity/internal/beadmeta"
)

func TestControllerMetadataTransitionPermitDigestMatchesAcceptedBeads(t *testing.T) {
	// Generated by issueops.ProtectedMutationDigest at accepted Beads commit
	// 3c3423cf09a9557a85d4bebf31a425f49511dfed, including its public request's
	// capitalized JSON fields, absent Expected, and cleared ProtectedPermit.
	for _, tc := range []struct {
		revision int64
		digest   string
	}{
		{-7, "0c8413c2e50c131a975ae02ce9ab6680533c681212c95d1ab03dc794795c5387"},
		{7, "f1bf9773dadc4b73f107153f566db2ccf16a49be3cd3ce9a7153dd35e37b7eeb"},
	} {
		value := json.RawMessage(`"child-head"`)
		request := ControllerMetadataTransitionRequest{
			ReceiptID: "child-anchor-1", Scope: "city:alpha/rig:fixture",
			Kind: "lifecycle_descendant_anchor_v1", Actor: "controller",
			ExpectedVersion: tc.revision, Key: beadmeta.LifecycleTransitionHeadMetadataKey,
			Value: &value, Payload: json.RawMessage(`{"schema_version":1,"parent":"source-1"}`),
		}
		digest, err := ControllerMetadataTransitionProtectedMutationDigest("gc-42", request)
		if err != nil || digest != tc.digest {
			t.Fatalf("revision %d digest = %q, err=%v; want accepted backend digest %q", tc.revision, digest, err, tc.digest)
		}
		request.ProtectedPermit = "opaque-signed-permit"
		withPermit, err := ControllerMetadataTransitionProtectedMutationDigest("gc-42", request)
		if err != nil || withPermit != digest {
			t.Fatalf("permit changed its own request digest: %q, %v", withPermit, err)
		}
		other, err := ControllerMetadataTransitionProtectedMutationDigest("gc-43", request)
		if err != nil || other == digest {
			t.Fatalf("digest did not bind exact issue identity: %q, %v", other, err)
		}
		request.ExpectedVersion = 0
		if _, err := ControllerMetadataTransitionProtectedMutationDigest("gc-42", request); err == nil {
			t.Fatal("zero revision produced a permit digest")
		}
	}
	if ControllerMetadataTransitionProtectedMutationOperation != "issue.revision_transition" {
		t.Fatal("metadata transition permit uses the wrong backend operation")
	}
}
